"""
pacote.py
---------
Este arquivo contem o projeto Corpo Dinamico inteiro (codigo + imagens),
compactado em texto. Ao ser executado, ele recria a estrutura de pastas
original (app/, assets/) no diretorio atual.

Gerado automaticamente - nao editar a mao.
"""
import os
import base64
import json

_DADOS = '''{"assets/logo/logo-icone.jpg": "", "assets/logo/logo-principal.jpg": "", "assets/logo/logo-icone.ico": "", "app/paths.py": "", "app/migrations_runner.py": "", "app/receipt_pdf.py": "", "app/auth.py": "", "app/audit_service.py": "", "app/email_queue.py": "", "app/finance_service.py": "", "app/receipts_service.py": "", "app/__init__.py": "IyBQYWNvdGUgcHJpbmNpcGFsIGRvIENvcnBvIERpbsOibWljby4K", "app/web.py": "", "app/settings_service.py": "", "app/dashboard_service.py": "", "app/money.py": "", "app/email_service.py": "", "app/backup_service.py": "", "app/reports_pdf.py": "", "app/students_service.py": "", "app/permissions.py": "", "app/system_health.py": "", "app/db.py": "", "app/crypto_utils.py": "", "app/logger.py": "", "app/static/style.css": "", "app/static/img/logo-icone.jpg": "", "app/static/img/logo-principal.jpg": "", "app/migrations/001_initial.sql": "", "app/migrations/003_permissoes_professor.sql": "", "app/migrations/002_comprovantes.sql": "", "app/templates/comprovante_detalhe.html": "", "app/templates/alunos_lista.html": "", "app/templates/configuracoes_assinatura.html": "", "app/templates/comprovantes.html": "", "app/templates/planos.html": "", "app/templates/configuracoes_professores.html": "", "app/templates/aluno_form.html": "", "app/templates/dashboard.html": "", "app/templates/backup.html": "", "app/templates/auditoria.html": "", "app/templates/aluno_editar.html": "", "app/templates/login.html": "", "app/templates/aluno_detalhe.html": "", "app/templates/setup.html": "", "app/templates/plano_editar.html": "", "app/templates/configuracoes_email.html": "", "app/templates/minha_senha.html": "", "app/templates/configuracoes.html": "", "app/templates/aluno_reativar.html": "", "app/templates/aluno_receber.html": "", "app/templates/erro.html": "", "app/templates/base.html": "", "app/templates/saude.html": "", "app/templates/relatorios.html": ""}'''


def unpack():
    arquivos = json.loads(_DADOS)
    criados = 0
    for rel_path, b64_content in arquivos.items():
        full_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), rel_path)
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        with open(full_path, "wb") as f:
            f.write(base64.b64decode(b64_content))
        criados += 1
    print(f"Projeto Corpo Dinamico reconstituido: {criados} arquivo(s) criado(s).")


if __name__ == "__main__":
    unpack()
